<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import CoalToolShell from '../components/CoalToolShell.vue'
import { tools, defaults, calculate, activeFields, type Values } from '../utils/coal/calculators'
import { lines } from '../utils/coal/blending'
import { saveRecord, downloadCSV, format, records } from '../utils/coal/storage'
const route=useRoute(),keyword=ref(''),category=ref(String(route.query.category||'全部')),values=ref<Values>({}),message=ref('')
const selected=computed(()=>tools.find(t=>t.id===route.params.id))
const categories=['全部','通用计算','工业分析','元素分析','工艺性能','其他测定']
const filtered=computed(()=>tools.filter(t=>(category.value==='全部'||t.category===category.value)&&`${t.name}${t.desc}`.includes(keyword.value.trim())))
watch(()=>route.fullPath,()=>{document.title=`${selected.value?.name||'矿业工具箱'} · 懂矿帝`;if(route.query.category)category.value=String(route.query.category);message.value='';if(selected.value){values.value=defaults(selected.value);if(route.query.record){const rec=records().find(x=>x.id===route.query.record);if(rec?.input&&typeof rec.input==='object'&&!Array.isArray(rec.input))values.value={...values.value,...rec.input as Values}}}}, {immediate:true})
const result=computed(()=>{try{return {rows:selected.value?calculate(selected.value,values.value):[],error:''}}catch(e){return {rows:[],error:e instanceof Error?e.message:'请核对输入'}}})
function reset(){if(selected.value)values.value=defaults(selected.value);message.value='已恢复示例。'}
function save(){if(!selected.value||result.value.error)return;try{saveRecord({name:selected.value.name,path:route.path,input:values.value,output:result.value.rows});message.value='已保存到本机测算记录。'}catch{message.value='浏览器存储不可用，未能保存；可导出 CSV。'}}
function exportResult(){if(!selected.value||result.value.error)return;downloadCSV(`${selected.value.name}.csv`,[['懂矿帝',selected.value.name],['时间',new Date().toLocaleString('zh-CN')],['输入项目','数值','单位'],...selected.value.fields.map(f=>[f.label,String(values.value[f.key]),f.unit]),[],['结果','数值','单位'],...result.value.rows.map(r=>[r.label,r.value,r.unit||'']),[],['公式',selected.value.formula],['说明',selected.value.note||selected.value.reference]])}
</script>
<template><CoalToolShell>
 <template v-if="!route.params.id">
  <section class="coal-hero"><div class="container coal-hero-grid"><div><p class="coal-eyebrow">懂矿帝 · 矿业工具箱</p><h1>算清煤价，<br>配好每一吨煤。</h1><p>从采购比价到煤质换算，从化验复核到经济配煤。<br>把专业计算放进日常工作，让每个结果有据可查。</p><div class="coal-hero-actions"><a class="coal-btn primary" href="#calculators">开始计算 <span>↓</span></a><RouterLink class="coal-btn light" to="/tools/coal">进入配煤专区 ↗</RouterLink></div></div><div class="coal-hero-board"><div class="coal-board-head"><span>采购测算示例</span><span class="coal-live">● 输入即算</span></div><div class="coal-board-row"><span>煤价</span><strong>780 <small>元/吨</small></strong></div><div class="coal-board-row"><span>低位热值</span><strong>5,500 <small>kcal/kg</small></strong></div><div class="coal-board-result"><span>每百万大卡成本</span><strong>141.82 <small>元</small></strong></div><p>780 × 1000 ÷ 5500</p><RouterLink to="/tools/calc/kajia">换成你的数据试算 →</RouterLink></div></div><div class="container coal-hero-stats"><span><b>27</b> 个计算工具</span><span><b>5</b> 条配煤产品线</span><span><b>0</b> 登录门槛</span><span>输入数据仅在你的浏览器计算</span></div></section>
  <section id="calculators" class="container coal-section"><div class="coal-section-head"><div><p class="coal-eyebrow">日常计算，一站完成</p><h2>煤炭计算工具</h2></div><label class="coal-search"><span>⌕</span><input v-model="keyword" type="search" placeholder="搜索工具，如 热值、灰分、卡价" aria-label="搜索计算工具"></label></div><div class="coal-filter"><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}} <small>{{c==='全部'?tools.length:tools.filter(t=>t.category===c).length}}</small></button></div><div class="coal-tool-grid"><RouterLink v-for="(t,i) in filtered" :key="t.id" :to="`/tools/calc/${t.id}`" class="coal-tool-card"><div><span class="coal-tool-symbol">{{String(i+1).padStart(2,'0')}}</span><span class="coal-tag">{{t.category}}</span></div><h3>{{t.name}} <span>↗</span></h3><p>{{t.desc}}</p><small>打开计算工具 →</small></RouterLink></div><div v-if="!filtered.length" class="coal-empty">未找到匹配工具，试试其他关键词。</div></section>
  <section class="container coal-section"><div class="coal-section-head"><div><p class="coal-eyebrow">从单项计算，到多煤源决策</p><h2>五大配煤专区</h2></div><RouterLink class="coal-text-link" to="/tools/coal">查看全部方案 →</RouterLink></div><div class="coal-lines-preview"><RouterLink v-for="(line,i) in lines" :key="line.id" :to="`/tools/coal/${line.id}`"><span>0{{i+1}}</span><h3>{{line.short}}</h3><p>{{line.desc}}</p><strong>开始测算 ↗</strong></RouterLink></div></section>
 </template>
 <section v-else-if="selected" class="container coal-section"><div class="coal-breadcrumb"><RouterLink to="/tools">矿业工具箱</RouterLink> / {{selected.category}} / {{selected.name}}</div><div class="coal-detail-heading"><span class="coal-tag">{{selected.category}}</span><h1>{{selected.name}}</h1><p>{{selected.desc}}</p></div><div class="coal-calculator-layout"><section class="coal-panel"><div class="coal-panel-heading"><h2>输入数据</h2><button class="coal-text-button" @click="reset">恢复示例 ↻</button></div><p class="coal-help">默认展示示例数据，请替换为你的实际数值。</p><div class="coal-field-grid"><label v-for="field in activeFields(selected,values)" :key="field.key" class="coal-field"><span>{{field.label}}</span><select v-if="field.options" v-model="values[field.key]"><option v-for="option in field.options" :key="option">{{option}}</option></select><div v-else class="coal-input-unit"><input v-model="values[field.key]" type="number" step="any" :min="field.min" :max="field.max" :aria-label="field.label"><span>{{field.unit}}</span></div></label></div></section><aside class="coal-panel coal-results"><div class="coal-panel-heading"><h2>计算结果</h2><span class="coal-live">● 实时更新</span></div><div v-if="result.error" class="coal-error" role="alert">{{result.error}}</div><template v-else><div class="coal-results-grid" aria-live="polite"><div v-for="(row,i) in result.rows" :key="row.label" :class="{'coal-result-main':i===0}"><span>{{row.label}}</span><strong>{{format(row.value,i===0?2:4)}} <small>{{row.unit}}</small></strong></div></div><div class="coal-actions"><button class="coal-btn primary" @click="save">保存测算</button><button class="coal-btn" @click="exportResult">导出 CSV</button></div></template><p v-if="message" class="coal-feedback" role="status">{{message}}</p><div class="coal-formula"><h3>计算公式</h3><p>{{selected.formula}}</p><small>{{selected.reference}}</small></div><div v-if="selected.note" class="coal-note">{{selected.note}}</div><p class="coal-help">结果为输入数据的算术测算，计价以合同为准；化验报告需按现行标准及试验程序复核。</p></aside></div><div class="coal-next-tools"><RouterLink v-for="t in tools.filter(t=>t.category===selected?.category&&t.id!==selected?.id).slice(0,4)" :key="t.id" :to="`/tools/calc/${t.id}`">{{t.name}} ↗</RouterLink></div></section>
 <section v-else class="container coal-empty"><h1>未找到该工具</h1><RouterLink to="/tools">返回全部工具 →</RouterLink></section>
 </CoalToolShell></template>
